import {handCard} from './hand-card.mjs';
export {handCard} from './hand-card.mjs';
import {GuandanMatch,chooseMove,interpretations,sortHand,rankText,wild,moveLabel,TYPE_NAMES} from './guandan.mjs';
import {chooseCompetitive} from './guandan-strategy.mjs';
import {Guandan3D} from './guandan3d.mjs';
const NAMES=['你','左家 · 对手','对家 · 队友','右家 · 对手'];
export const GUANDAN_RULES=`<p>四人对家：你与正对面的牌手一队，左右两家为另一队。两副牌共 108 张，每人 27 张。此桌不下注、不消耗筹码，角色技能关闭。</p><ol><li>从打 2 开始。大王 ＞ 小王 ＞ 级牌 ＞ A 至 2。红心级牌是逢人配，可代替非王牌；单出仍是级牌。</li><li>普通牌型：单张、对子、三张、三带二、五张顺子、三连对、两组三张相连的钢板。接牌必须同型、同张数且更大；连续牌型中的级牌按原点数，A 可作最小或最大。</li><li>四王炸最大，其次六张及以上炸弹、同花顺、五张炸弹、四张炸弹。普通炸弹先比张数再比点数。同花顺为五张同花连续牌。</li><li>选中手牌后，界面会列出可用牌型；逢人配有多种解释时可选择。提示会选中一组合法牌，需点击出牌确认。</li><li>无人接牌时由最后出牌者重新领出；若其已出完，存活队友接风。头游与队友分别为前两名升 3 级、第一及第三升 2 级、第一及末游升 1 级。</li><li>每副结束可继续升级赛。下副末游向头游进贡最大非逢人配牌；双下双方进贡，大贡给头游。两张大王可抗贡。你收到贡牌时自行选择不超过 10 的非逢人配牌还贡。电脑自动还贡。</li><li>此练习桌达到 A 后，打 A 方取得头游且队友不是末游，即赢得升级赛；未过 A 则继续争夺，不设三次未过退级。极少数无合法小牌可还时自动允许最小非逢人配牌。</li></ol><p>电脑比较出牌后的整手拆分，结合公开牌估计控制力，并考虑队友接风、送牌和对手报单报双。策略在线程中计算，只读取自身手牌和公开行动，不查看你的暗牌；属于启发式竞技策略。规则参考 <a href="https://www.szai.edu.cn/gh/info/1133/1991.htm" target="_blank" rel="noopener">掼蛋牌型与升级规则</a>；本站采用上文列出的练习桌约定。</p>`;

export class GuandanUI{
 constructor(host,{onExit,onRules,toast,beep,role=0,reduced=false,network=null,roster=null}){Object.assign(this,{host,onExit,onRules,toast,beep,reduced,network});this.match=new GuandanMatch();this.selected=new Set();this.choice=null;this.alive=true;this.busy=false;this.hintIndex=0;this.q=s=>host.querySelector(s);document.body.classList.add('in-game','guandan-game');host.innerHTML=`<section class="gd-room"><div class="gd-stage"><div class="gd-seat-labels"></div></div><header class="gd-heading"><div><small>THE BRICK CLUB / FIRST PERSON</small><h1>掼蛋 <span>四人对家</span></h1></div><button data-gfull>⛶ 全屏</button><button data-grules>玩法</button><button data-gexit>离开牌桌 ↗</button></header><div class="gd-score"></div><div class="gd-tableplay"></div><div class="gd-seat-plays gd-play-feed" aria-label="全桌出牌记录"></div><div class="gd-hand-area"></div><div class="gd-controls"></div><div class="gd-end"></div></section>`;this.q('[data-gexit]').onclick=()=>this.exit();this.q('[data-grules]').onclick=onRules;this.q('[data-gfull]').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('可使用浏览器全屏功能')}};
 try{this.scene=new Guandan3D(this.q('.gd-stage'),{role,mode:'poker',roster:roster??[{seed:1512},{seed:4233},{seed:8215}],reduced,onSound:beep});this.scene.foreground.visible=false}catch(e){console.warn('Guandan WebGL unavailable',e);this.toast('此设备无法显示 3D，仍可使用完整选牌界面')}
 if(!network)this.start()
 }
 start(){if(this.network){this.network.next();return}this.selected.clear();this.choice=null;this.hintIndex=0;this.playSignature=null;this.lastEffectAction=null;this.game=this.match.start();this.message='你与正对面的牌手一队。';if(this.game.tributeLog.length)this.message=this.game.tributeLog.join(' · ');this.busy=false;this.render();this.run()}
 options(){const cards=this.game.hands[0].filter(c=>this.selected.has(c.id));return interpretations(cards,this.game.level,this.game.target)}
 render(){if(!this.alive)return;const g=this.game,returning=g.returns?.length>0,humanReturn=returning&&g.returns[0].from===0,canSelect=!g.done&&!this.busy&&((!returning&&g.turn===0)||humanReturn),opts=returning?[]:this.options(),chosen=opts.find(m=>m.key===this.choice)||opts[0];this.choice=chosen?.key??null;if(this.dealRound!==this.match.round){this.dealRound=this.match.round;if(!g.actions.length)this.beep?.('deal')}
 this.q('.gd-score').innerHTML=`<div><span class="gd-level">打 ${rankText(g.level)}</span><b>我方 ${rankText(this.match.levels[0])} <i>VS</i> 对方 ${rankText(this.match.levels[1])}</b><small>第 ${this.match.round} 副 · ♥${rankText(g.level)} 逢人配</small></div><details><summary>本副记录</summary><div>${g.tributeLog.map(s=>'<p>'+s+'</p>').join('')}${g.actions.slice(-18).map(a=>`<p>${(this.names??NAMES)[a.seat]}：${a.pass?'不出':a.move+' '+a.cards.map(c=>c.s+rankText(c.r)).join(' ')}</p>`).join('')||'<p>等待首家出牌</p>'}</div></details>`;
 this.q('.gd-seat-labels').innerHTML=[1,2,3].map(i=>`<div data-seat-label="${i}" data-at-head="true" class="gd-seat ${i===2?'teammate':''} ${!g.done&&g.turn===i&&!returning?'active':''}"><strong>${(this.names??NAMES)[i]}</strong><span>${g.hands[i].length?'余 '+g.hands[i].length+' 张':['头游','二游','三游','末游'][g.finish.indexOf(i)]}</span></div>`).join('');
 const target=g.target;this.scene?.showPlays(g.last,g.trick);this.scene?.showTurn(returning?g.returns[0].from:g.turn,g.done);this.q('.gd-tableplay').innerHTML=`<div class="gd-turn-message" role="status" aria-live="polite">${g.done?'本副结束':returning?humanReturn?'请选择一张牌还贡':'正在进贡 / 还贡':this.busy?(this.names??NAMES)[g.turn]+'正在思考…':g.turn===0?target?'轮到你接牌':'轮到你领出新一轮':(this.names??NAMES)[g.turn]+'出牌'}</div>${returning?'<div class="gd-open-table">'+g.tributeLog.slice(-2).join('<br>')+'</div>':''}`;
 this.renderPlays();
 const hand=sortHand(g.hands[0],g.level),rows=[hand],allowed=humanReturn?this.match.returnOptions(0):[];
 const handScroll=this.q('.gd-hand-scroll')?.scrollLeft??0;this.q('.gd-hand-area').innerHTML=`<div class="gd-hand-heading"><b>你的手牌 <span>${hand.length} 张</span></b><span>${humanReturn?'还贡：选 10 以下（含 10）的非逢人配牌':canSelect?'点击选牌 · 再点取消':'等待行动'}</span><span class="gd-team-note">正对面是你的队友</span></div><div class="gd-hand-scroll">${rows.map(row=>`<div class="gd-hand-row" style="--count:${Math.max(1,row.length)}">${row.map(c=>handCard(c,g.level,{selected:this.selected.has(c.id),disabled:!canSelect||humanReturn&&allowed.length>0&&!allowed.some(x=>x.id===c.id)})).join('')}</div>`).join('')}</div>`;
 this.q('.gd-hand-scroll').scrollLeft=handScroll;this.q('.gd-controls').innerHTML=`<div class="gd-selection"><strong>${humanReturn?'还贡':chosen?moveLabel(chosen):this.selected.size?'当前选牌无法出牌':'已选 0 张'}</strong>${opts.length>1?`<select data-gtype aria-label="选择逢人配组成的牌型">${opts.map(m=>`<option value="${m.key}" ${m.key===this.choice?'selected':''}>${moveLabel(m)}${m.suit?' · '+m.suit:''}</option>`).join('')}</select>`:`<small>${humanReturn?'选一张后确认':this.message}</small>`}</div><div class="gd-actions"><button data-gclear ${!canSelect?'disabled':''}>取消</button><button data-ghint ${!canSelect||returning?'disabled':''}>提示</button><button data-gpass ${!canSelect||!target||returning?'disabled':''}>不出</button><button class="gd-play-button" data-gplay ${!canSelect||(humanReturn?this.selected.size!==1:!chosen)?'disabled':''}>${humanReturn?'确认还贡':'出牌'} ↗</button></div>`;
 this.host.querySelectorAll('[data-gcard]').forEach(b=>b.onclick=()=>{const id=+b.dataset.gcard;if(this.selected.has(id))this.selected.delete(id);else{if(humanReturn)this.selected.clear();this.selected.add(id)}this.choice=null;this.render()});const select=this.q('[data-gtype]');if(select)select.onchange=e=>{this.choice=e.target.value;this.render()};this.q('[data-gclear]').onclick=()=>{this.selected.clear();this.choice=null;this.render()};this.q('[data-ghint]').onclick=()=>this.hint();this.q('[data-gpass]').onclick=()=>this.play(true);this.q('[data-gplay]').onclick=()=>this.play(false);
 this.q('.gd-end').innerHTML=g.done?this.resultMarkup():'';if(g.done){this.q('[data-gnext]').onclick=()=>{if(!this.network&&this.match.champion!==null)this.match=new GuandanMatch();this.start()};this.q('[data-gback]').onclick=()=>this.onExit()}
 }
 renderPlays(){const g=this.game,signature=JSON.stringify([g.actions.slice(-4),g.owner,g.target?.key]);if(signature===this.playSignature)return;this.playSignature=signature;
 const actions=g.actions.slice(-4);this.q('.gd-seat-plays').innerHTML=actions.length?actions.map((a,n)=>`<div class="gd-feed-entry ${n===actions.length-1?'latest':''}"><strong>${(this.names??NAMES)[a.seat]}</strong><span>${a.pass?'不出':a.move}</span><small>${a.pass?'':a.cards.map(c=>c.s+rankText(c.r)).join(' ')}</small>${!a.pass&&a.seat===g.owner&&n===actions.length-1?'<b>当前领出</b>':''}</div>`).join(''):'<span class="gd-feed-empty">等待首家出牌</span>';
 }
 async decision(snapshot){if(!this.worker){try{this.worker=new Worker('./guandan-worker.mjs',{type:'module'});this.jobs=new Map();this.jobId=0;this.worker.onmessage=({data})=>{const j=this.jobs.get(data.id);if(!j)return;clearTimeout(j.timer);this.jobs.delete(data.id);data.error?j.reject(Error(data.error)):j.resolve(data.move)};this.worker.onerror=()=>{for(const j of this.jobs.values()){clearTimeout(j.timer);j.reject(Error('策略线程不可用'))}this.jobs.clear();this.worker.terminate();this.worker=null}}catch{return chooseCompetitive(snapshot)}}return new Promise((resolve,reject)=>{const id=++this.jobId,timer=setTimeout(()=>{this.jobs.delete(id);reject(Error('策略计算超时'))},6000);this.jobs.set(id,{resolve,reject,timer});this.worker.postMessage({id,snapshot})})}
 resultMarkup(){const r=this.match.settle(),g=this.game;return`<div class="gd-result gd-review"><div class="gd-review-hands">${g.hands.map((hand,i)=>`<section><b>${(this.names??NAMES)[i]} · 剩余 ${hand.length} 张</b><div>${sortHand(hand,g.level).map(c=>handCard(c,g.level,{small:true})).join('')||'<span>已出完</span>'}</div></section>`).join('')}</div><small>${r.champion!==null?'升级赛结束':'本副结束 · 剩余手牌公开'}</small><h2>${r.team===0?'我方获胜':'对方获胜'}${r.champion!==null?' · 成功过 A':''}</h2><p>${g.finish.map((i,n)=>(n>=2&&g.finish[0]%2===g.finish[1]%2?'双下':['头游','二游','三游','末游'][n])+'：'+(this.names??NAMES)[i]).join('　')}</p><strong>${r.champion!==null?'本场升级赛完成':'升 '+r.gain+' 级 · '+rankText(r.before)+' → '+rankText(r.after)}</strong><div><button data-gback>返回大厅</button><button class="gd-play-button" data-gnext>${r.champion!==null?'新升级赛':'下一副 · 继续升级'} ↗</button></div></div>`}
 async hint(){if(this.busy)return;const g=this.game;this.busy=true;this.render();let recommended;try{recommended=await this.decision(g.snapshot(0))}catch{recommended=chooseCompetitive(g.snapshot(0))}if(!this.alive||this.game!==g)return;this.busy=false;const all=g.legal(0);if(!all.length){this.message='没有能压过的牌，可以选择不出。';this.selected.clear();this.render();return}if(!recommended&&g.owner===2)this.message='队友占先，建议不出；也可使用提示牌。';const ordered=recommended?[recommended,...all.filter(m=>m.key!==recommended.key)]:all;const m=ordered[this.hintIndex++%ordered.length];this.selected=new Set(m.cards.map(c=>c.id));this.choice=m.key;this.render()}
 async play(pass){if(this.busy||this.game.done)return;if(this.network){this.busy=true;try{await this.network.send({ids:pass?[]:[...this.selected],key:pass?null:this.choice});this.selected.clear();this.choice=null;this.hintIndex=0}catch{}finally{this.busy=false;if(this.alive)this.render()}return}try{if(this.game.returns.length){if(this.game.returns[0].from!==0)return;this.match.giveBack([...this.selected][0]);this.message=this.game.tributeLog.at(-1)}else{if(this.game.turn!==0)return;const m=this.game.act(0,pass?[]:[...this.selected],pass?null:this.choice);this.scene?.react(0);this.beep(m?.tier?'win':'tap');this.message=m?moveLabel(m):'你选择不出'}this.selected.clear();this.choice=null;this.hintIndex=0;if(this.game.done)this.match.settle();this.render();await this.run()}catch(e){this.toast(e.message)}}
 async pause(ms){await new Promise(r=>{this.waitResolve=r;this.timer=setTimeout(()=>{this.waitResolve=null;r()},this.reduced?80:ms)})}
 async run(){if(this.network||this.busy)return;const g=this.game;while(this.alive&&this.game===g&&!g.done){if(g.returns.length){if(g.returns[0].from===0){this.busy=false;this.render();return}this.busy=true;this.render();await this.pause(650);if(!this.alive||this.game!==g)return;this.match.autoReturn();this.message=g.tributeLog.at(-1);this.busy=false;continue}if(g.turn===0){this.busy=false;this.render();return}this.busy=true;this.render();const i=g.turn,snapshot=g.snapshot(i);const [m]=await Promise.all([this.decision(snapshot).catch(()=>chooseCompetitive(snapshot)),this.pause(950)]);if(!this.alive||this.game!==g)return;g.act(i,m?.cards.map(c=>c.id)||[],m?.key);this.scene?.react(i);this.beep(m?.tier?'win':'tap');this.message=(this.names??NAMES)[i]+' · '+(m?moveLabel(m):'不出');if(g.done)this.match.settle();this.render();await this.pause(450)}if(this.alive&&this.game===g){this.busy=false;this.render()}}
 exit(){if(this.network){this.network.exit();return}if(!this.game.done&&!confirm('离开将结束这场掼蛋练习，筹码不受影响。确定离开？'))return;this.onExit()}
 destroy(){this.alive=false;this.worker?.terminate();for(const j of this.jobs?.values()||[]){clearTimeout(j.timer);j.reject(Error('已离桌'))}this.jobs?.clear();clearTimeout(this.timer);this.waitResolve?.();this.scene?.destroy();document.body.classList.remove('guandan-game')}
}
